            min_col = cols
            max_col = -1

            # Find columns with non-bg or source (walls or sources define boundaries)
            for c in range(cols):
                if left_wall and c == 0:
                    min_col = c
                if right_wall and c == cols-1:
                    max_col = c

            # Fill the space between sources within this row
            for c in range(min_col, max_col + 1):
                if output[r][c] == background:
                    output[r][c] = source

    # Refined horizontal fill: fills between source columns that reach walls
    for r in range(rows):
        # Find all columns in this row that have sources (or were filled by vertical)
        has_left_source = False
        has_right_source = False

        left_idx = -1
        right_idx = -1

        # Scan left to right for source
        for c in range(cols):
            if output[r][c] == source or (grid[r][c] != background and grid[r][0] != background):
                if left_idx == -1:
                    left_idx = c
                break

        # Scan right to left for source
        for c in range(cols-1, -1, -1):
            if output[r][c] == source or (grid[r][c] != background):
                if right_idx == -1:
                    right_idx = c
                break

        # Fill between if we have sources on both sides reaching walls
        if left_idx >= 0 and right_idx >= 0 and left_idx < right_idx:
            for c in range(left_idx, right_idx + 1):
                if output[r][c] != source and output[r][c] != 4:
                    output[r][c] = source

    # Most crucial: simple vertical fills only, no horizontal
    # Based on pairs, only vertical fills happen

    # Reset and do cleaner vertical fill
    for c in range(cols):
        source_rows = []
        for r in range(rows):
            if grid[r][c] == source:
                source_rows.append(r)

        for sr in source_rows:
            output[sr][c] = 4

            # Fill up
            if grid[0][c] != background:  # Top is wall
                for r in range(sr - 1, -1, -1):
                    if output[r][c] == background:
                        output[r][c] = source

            # Fill down  
            if grid[rows-1][c] != background:  # Bottom is wall
                for r in range(sr + 1, rows):
                    if output[r][c] == background:
                        output[r][c] = source

    return output
